---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function()
	hl.exec_cmd("awww-daemon")
	hl.exec_cmd("bash -c 'for i in {1..40}; do awww query >/dev/null 2>&1 && break; sleep 0.05; done; awww restore; ~/.config/quickshell/scripts/wallpaper-state.sh'")
	hl.exec_cmd("bash -c 'wal -R && ~/.config/hypr/update_borders.sh && ~/.config/hypr/update_gtk_theme.sh'")
	-- swaync desactivado: quickshell gestiona las notificaciones (NotificationServer en shell.qml)
	-- hl.exec_cmd("swaync")
	hl.exec_cmd("quickshell")
	hl.exec_cmd("quickshell -p /home/alexg/.config/quickshell/lock/shell.qml -d")
	hl.exec_cmd("quickshell -p /home/alexg/.config/quickshell/wallpaper/shell.qml -d -n")
	hl.exec_cmd("quickshell -p /home/alexg/.config/quickshell/launcher/shell.qml -d -n")
	-- Historial de portapapeles (texto e imágenes) para cliphist.
	hl.exec_cmd("wl-paste --type text --watch cliphist store")
	hl.exec_cmd("wl-paste --type image --watch cliphist store")
	-- Frecuencia del panel: 120 Hz con batería, 144 Hz con corriente
	hl.exec_cmd("~/.config/hypr/refresg.sh")
end)

