})

-- Curvas y animaciones: https://wiki.hypr.land/configuring/core/animations/
--
-- Objetivo: que las ventanas se abran y cierren con el mismo aire que el
-- launcher de quickshell (salida rapida tipo OutExpo, ~150-250 ms) y con un
-- rebote sutil al abrir, en vez del "linear" mecanico de antes.
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1 } } })
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })

-- Curvas nuevas "estilo launcher" (el launcher usa OutExpo de 150 ms):
--   swiftOut = OutExpo (arranque instantaneo, asentamiento suave)
--   popOut   = OutExpo con rebote (y > 1 -> la escala se pasa y vuelve)
--   swiftIn  = aceleracion final (para cuando algo debe desaparecer deprisa)
hl.curve("swiftOut", { type = "bezier", points = { { 0.14, 1 }, { 0.24, 1 } } })
hl.curve("swiftIn", { type = "bezier", points = { { 0.45, 0 }, { 0.75, 0 } } })
hl.curve("popOut", { type = "bezier", points = { { 0.32, 1.42 }, { 0.62, 1 } } })

-- Muelles: mass = 1 y se ajustan rigidez/amortiguacion.
-- OJO: en los springs el campo "speed" no interviene; el tiempo lo marcan
-- stiffness/dampening (simulados: ~167 ms al 100%, estable a los ~420 ms).
hl.curve("easy", { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })
hl.curve("snappy", { type = "spring", mass = 1, stiffness = 600, dampening = 39 })

hl.animation({ leaf = "global", enabled = true, speed = 8, bezier = "default" })
hl.animation({ leaf = "border", enabled = true, speed = 5.39, bezier = "easeOutQuint" })
-- Ventanas: abrir con "pop" (escala con rebote) y cerrar rapido y suave.
hl.animation({ leaf = "windows", enabled = true, speed = 3, spring = "snappy" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 1.5, bezier = "popOut", style = "popin 88%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.3, bezier = "swiftOut", style = "popin 88%" })
-- Fundidos rapidos y suaves (antes casi lineales).
hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.5, bezier = "swiftOut" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.3, bezier = "swiftOut" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.03, bezier = "quick" })
-- Capas (launcher, barra, wallpaper): a 150 ms con OutExpo, como el launcher.
hl.animation({ leaf = "layers", enabled = true, speed = 1.5, bezier = "swiftOut" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 1.5, bezier = "swiftOut", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.5, bezier = "swiftOut", style = "fade" })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.5, bezier = "swiftOut" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.5, bezier = "swiftOut" })
-- Escritorios: transicion rapida.
hl.animation({ leaf = "workspaces", enabled = true, speed = 1.5, bezier = "swiftOut", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 1.3, bezier = "swiftOut", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 1.5, bezier = "swiftOut", style = "fade" })
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

