hl.config({
	input = {
		-- Dos layouts: "es" (espanol) y "us" (ingles). El primero es el que
		-- se usa para resolver los atajos. Se conmutan con:
		--   hyprctl switchxkblayout all next   (atajo SUPER + K)
		-- Ademas "grp:alt_shift_toggle" permite alternar con ALT + SHIFT
		-- de forma nativa de XKB (instantanea, funciona en cualquier app).
		kb_layout = "es,us",
		kb_variant = "",
		kb_model = "",
		kb_options = "grp:alt_shift_toggle",
		kb_rules = "",

		follow_mouse = true, -- If true, the focus will follow the mouse pointer.

		-- Nota (alexg): el raton va 1:1 sin aceleracion (flat), pero el
		-- TRACKPAD usa "adaptive" mas abajo: en un trackpad, ir 1:1 sin
		-- suavizado se percibe como impreciso y con retraso.
		sensitivity = 0.1, -- -1.0 - 1.0, 0 means no modification.
		accel_profile = "flat", -- Raton sin aceleracion
		-- force_no_accel ya NO va aqui: era global y tambien afectaba al
		-- touchpad, desactivando el suavizado/filtro de temblor de libinput.
		-- Cada dispositivo lo define ahora en su propio hl.device.

		touchpad = {
			natural_scroll = true,
			tap_to_click = true,
			clickfinger_behavior = true, -- 2 dedos = clic derecho, 3 = medio
			disable_while_typing = true,
		},
	},
})

hl.gesture({
	fingers = 3,
	direction = "horizontal",
	action = "workspace",
})

-- Gesto de 3 dedos vertical:
--   arriba -> pantalla completa    abajo -> alternar ventana flotante
hl.gesture({
	fingers = 3,
	direction = "up",
	action = "fullscreen",
})
hl.gesture({
	fingers = 3,
	direction = "down",
	action = "float",
})

-- Example per-device config
-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/ for more
hl.device({
	name = "asue120a:00-04f3:319b-touchpad",
	sensitivity = 0.15, -- Ligeramente subido (antes 0)
	accel_profile = "adaptive", -- Perfil correcto para trackpad (fluido y preciso)
	-- force_no_accel no se puede poner por dispositivo en este parser;
	-- el suavizado/filtro lo gestiona libinput con accel_profile "adaptive".
})
hl.device({
	name = "logitech-g-pro--1",
	sensitivity = 0.1, -- -1.0 - 1.0, 0 means no modification.
	accel_profile = "flat", -- Desactiva la aceleracion del raton
})

