-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Barra superior de Quickshell: desenfoca el fondo para el efecto cristal.
hl.layer_rule({
	name = "quickshell-bar-blur",
	match = { namespace = "^quickshell-bar$" },
	blur = true,
})

-- Lanzador (Spotlight / Launchpad): blur real sólo en las zonas opacas del
-- panel. El resto de la superficie es transparente, así que ignore_alpha evita
-- difuminar toda la pantalla. En modo Launchpad el velo oscuro también se
-- difumina y da el fondo borroso típico de macOS.
hl.layer_rule({
	name = "quickshell-launcher-blur",
	match = { namespace = "^launcher$" },
	blur = true,
	ignore_alpha = 0.15,
})

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

-- Thunar y diálogos de archivos: opacidad sutil (el CSS de gtk.css quita el fondo
-- opaco; esta regla deja ver el fondo difuminado del blur de Hyprland).
-- El dialogo de archivos GTK de otras apps suele tener class "thunar" o similar;
-- ajusta el 0.9 si lo quieres mas o menos transparente (1.0 = opaco).
hl.window_rule({
	name = "thunar-opacity",
	match = { class = "^(thunar|Thunar|org.gnome.Nautilus|xdg-desktop-portal-gtk)$" },

	opacity = "0.92 0.88",
})
